class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total = 0
        n = len(nums)
        for i in range(n):
            # Check if index i - k exists
            left_ok = True
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    left_ok = False
            # Check if index i + k exists
            right_ok = True
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    right_ok = False
            # If both conditions are satisfied (or indices don't exist), it's good
            if left_ok and right_ok:
                total += nums[i]
        return total
