class Solution:
    def totalNumbers(self, digits: List[int]) -> int:
        from collections import Counter
        count = Counter(digits)
        distinct = set()

        # Get all unique digits available
        unique_digits = list(count.keys())

        # Try all possible 3-digit numbers
        for d1 in unique_digits:
            if d1 == 0:
                continue  # No leading zeros
            for d2 in unique_digits:
                for d3 in unique_digits:
                    # Check if the number is even
                    if d3 % 2 != 0:
                        continue
                    # Check if we have enough copies of each digit
                    # We need to check the frequency of each digit in the combination
                    combo = [d1, d2, d3]
                    freq = Counter(combo)
                    valid = True
                    for digit, cnt in freq.items():
                        if count[digit] < cnt:
                            valid = False
                            break
                    if valid:
                        num = d1 * 100 + d2 * 10 + d3
                        distinct.add(num)

        return len(distinct)
